var numberOfBottles = 99;
while (numberOfBottles >= 0) {
  var bottleWord = "bottle";
  if (numberOfBottles === 1) {
    bottleWord = "bottles";   // bug: should be the other way round
  }
  console.log(numberOfBottles + " " + bottleWord + " of beer on the wall");
  console.log(numberOfBottles + " " + bottleWord + " of beer,");
  console.log("Take one down, pass it around,");
  numberOfBottles--;
  console.log(numberOfBottles + " " + bottleWord + " of beer on the wall.");
}

function bottleText(n) {
  if (n === 0) return "No more bottles";
  if (n === 1) return "1 bottle";
  return n + " bottles";
}

let n = 99;
while (n > 0) {
  console.log(bottleText(n) + " of beer on the wall,");
  console.log(bottleText(n) + " of beer.");
  console.log("Take one down, pass it around,");
  n--;
  console.log(bottleText(n) + " of beer on the wall.");
  console.log("");
}

